#include <iostream>

int main() {
    int n = 0, previous = 0;
    std::cin >> n >> previous;
    int rises = 0;
    for (int i = 1; i < n; ++i) {
        int current = 0;
        std::cin >> current;
        if (current > previous) { ++rises; }
        previous = current;
    }
    std::cout << rises;
}

#include <iostream>
#include <iomanip>

int main() {
    int n = 0, best = 0;
    std::cin >> n >> best;
    long long sum = best;
    for (int i = 1; i < n; ++i) {
        int value = 0;
        std::cin >> value;
        sum += value;
        if (value > best) { best = value; }
    }
    std::cout << best << " " << std::fixed << std::setprecision(2) << static_cast<double>(sum) / n;
}

