    for (auto& x : a) { std::cin >> x; }
    long long x = 0; std::cin >> x;
    auto first = std::lower_bound(a.begin(), a.end(), x);
    auto last = std::upper_bound(a.begin(), a.end(), x);
    std::cout << last-first;
}

