    while (q--) { long long lo = 0, hi = 0; std::cin >> lo >> hi; if (lo > hi) { std::cout << "0\n"; continue; } auto first = std::lower_bound(a.begin(), a.end(), lo); auto last = std::upper_bound(a.begin(), a.end(), hi); std::cout << last-first << "\n"; }
